import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError(f"File {file_path} does not exist.")
    with open(file_path, 'r') as f:
        data = json.load(f)
    for req in INPUT_JSON["required"]:
        if req not in data:
            raise ValueError(f"Missing required attribute: {req}")
    for prop, schema in INPUT_JSON["properties"].items():
        if prop in data and not isinstance(data[prop], schema["type"]):
            raise ValueError(f"Attribute {prop} must be of type {schema['type'].__name__}.")
    if attribute == "email":
        if not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError("Invalid email format.")
    return data[attribute]

