import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")

    if not data:
        raise ValueError("Empty JSON data")

    countries = []
    populations = []
    for item in data:
        if not isinstance(item.get('country'), str):
            raise ValueError("Non-string country name found")
        if not isinstance(item.get('population'), (int, float)) or item['population'] < 0:
            raise ValueError("Invalid population value")
        countries.append(item['country'])
        populations.append(math.floor(item['population']))

    df = pd.DataFrame({'Country': countries, 'Population': populations})
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except IOError:
        raise IOError("Cannot write to file")

    return file_path, df

